contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint amount) public payable {
        require(amount <= address(c).balance);

        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        address beforeOwner = c.owner(); if (__ESBMC_reverted()) return;
        uint beforeBal = address(c).balance;

        c.withdraw(amount); if (__ESBMC_reverted()) return;

        uint afterCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        address afterOwner = c.owner(); if (__ESBMC_reverted()) return;
        uint afterBal = address(c).balance;

        assert(afterBal == beforeBal - amount && afterCount == beforeCount && afterOwner == beforeOwner);
    }
}

